Item.method_code:
/*
    WF遷移時の行う様々な事を処理している
    ・Vote時コメントの取得
    ・否認・仮承認時のコメント空欄時の警告
    ・全WFごとで担当者取得
    ・担当者の役割が全種揃っているかのチェック
    ・メール送信対象者にメールアドレスが存在するかチェック
    ・否認時の指摘追加処理
    ・メール構築用の値を作成（ここではメールを出さずに、次アサインメントのOnAssignで値を使ってメールを出す）

*/


Innovator inn = this.getInnovator();
string currentUserId = inn.getUserID();
string activityId = this.getProperty("id");
string errorMessage = "システムエラーです。管理者に連絡してください。";
string pathLabel = "";
bool isExist_Creater = false;
bool isExist_Reviewer = false;
bool isExist_Approver = false;
List<string> ccList = new List<string>();
List<Item> voteList = new List<Item>();

// 必要資料のやるやら承認依頼系
string YryrReviewPathName = "YryrReview";
string YryrApprovePathName = "YryrApprove";
string YryrRejectPathName = "YryrReject";

// 確認中への遷移パス名 （全対象アイテムで共通）
string RequestReviewPathName = "Request Review";

// メールでのコメント部フォーマット
string MailCommentFormat = "<br>{0} :<br>{1}<br>";

// メールを飛ばすpullback系のパス名 これらは処理を飛ばす
List<string> pullbackTypeList = new List<string>
{
    "pullBack",
    "pullBack_RA_IP"
};

using (CCO.Permissions.GrantIdentity(Aras.Server.Security.Identity.GetByName("Administrators")))
{
    List<string> selectPropertyList = new List<string>
    {
        "h4_event",
        "h4_model_code",
        "h4_my",
        "h4_destination",
        "h4_model_name",
        "h4_pare_mq",
        "keyed_name",
        "managed_by_id",
        "h4_evaluation_unit",
        "h4_unique_event"
    };
    string selectProperty = string.Join(",", selectPropertyList);

    //アクティビティアサインメントとパス名、コメントを取得
    Item sourceAssignment = inn.newItem("Activity Assignment","get");
    sourceAssignment.setProperty("source_id",activityId);
    sourceAssignment.setAttribute("select", "comments,closed_on,path,related_id,closed_by");
    sourceAssignment = sourceAssignment.apply();
    
    if(sourceAssignment.isError() && sourceAssignment.getItemCount() == -1)
    {
        //エラー
        errorMessage = CCO.ErrorLookup.Lookup("h4_S_E_0002");
        return inn.newError(errorMessage);
    }
    
    Item tempSourceAssignment = null;
    List<Item> SourceAssignmentList = new List<Item>();
    DateTime assignClose = DateTime.MinValue;
    
    for(int i= 0;i < sourceAssignment.getItemCount();i++)
    {
        if(!string.IsNullOrEmpty(sourceAssignment.getItemByIndex(i).getProperty("comments")))//同アクティビティからコメントのあるアサインメントを取得
        {
            SourceAssignmentList.Add(sourceAssignment.getItemByIndex(i));
        }
        if(!string.IsNullOrEmpty(sourceAssignment.getItemByIndex(i).getProperty("closed_on")))
        {
            if(assignClose == DateTime.MinValue)
            {
                assignClose = DateTime.Parse(sourceAssignment.getItemByIndex(i).getProperty("closed_on"));
                tempSourceAssignment = sourceAssignment.getItemByIndex(i);
            }
            if(DateTime.Parse(sourceAssignment.getItemByIndex(i).getProperty("closed_on")) > assignClose)
            {
                assignClose = DateTime.Parse(sourceAssignment.getItemByIndex(i).getProperty("closed_on"));
                tempSourceAssignment = sourceAssignment.getItemByIndex(i);
            }
        }
    }

    string pathName = tempSourceAssignment.getProperty("path");
    bool isYryrReviewType = false;// 必要資料のやるやら承認依頼系統のpath
    if(pathName == YryrReviewPathName || pathName == YryrApprovePathName || pathName == YryrRejectPathName)
    {
        isYryrReviewType = true;
    }
    bool isRequestReviewPath = false;//作業中から確認中へ進むpathか？
    if(pathName == RequestReviewPathName)
    {
        isRequestReviewPath = true;
    }
    
    string comment = "";
    string voteIdentityId = "";
    var userCommentList = new List<string>();
    for(int i= 0;i < sourceAssignment.getItemCount();i++)
    {
        if(sourceAssignment.getItemByIndex(i).getProperty("path") == pathName)
        {
            voteIdentityId = sourceAssignment.getItemByIndex(i).getProperty("related_id");//IdentityID
            
            //エイリアスアイデンティティだけが担当者に設定される
            Item voteAlias = inn.newItem("Alias","get");
            voteAlias.setProperty("related_id",voteIdentityId);
            voteAlias = voteAlias.apply();
            Item voteUser = inn.newItem("User","get");
            voteUser.setAttribute("id",voteAlias.getProperty("source_id"));
            voteUser = voteUser.apply();
            voteList.Add(voteUser);
            ccList.Add(voteUser.getProperty("email"));
        }
    }

    //否認と仮承認ではコメントが空欄なら処理を止める + やるやらの承認依頼の否認でも
    if(pathName == "Reject" || pathName == "ProvisionalApprove" || pathName ==YryrRejectPathName)
    {
        if(string.IsNullOrWhiteSpace(tempSourceAssignment.getProperty("comments")))
        {
            errorMessage = CCO.ErrorLookup.Lookup("h4_S_E_0811");
            return inn.newError(errorMessage);
        }
    }
    



    
    if(!pullbackTypeList.Contains(pathName))//引き戻し以外の場合
    {
        for(int i = 0;i < SourceAssignmentList.Count;i++)
        {
            comment += "コメント"+(i+1).ToString()+"（"+SourceAssignmentList[i].getProperty("path")+"）"+"："+SourceAssignmentList[i].getProperty("comments")+Environment.NewLine;
            
            var targetUser = inn.newItem("User","get");
            targetUser.setID(SourceAssignmentList[i].getProperty("closed_by"));
            targetUser.setAttribute("select","keyed_name");
            targetUser = targetUser.apply();
            if(targetUser.isError())
            {
                return inn.newError(CCO.ErrorLookup.Lookup("h4_S_E_0002"));
            }
            var tmpMailComment = String.Format(MailCommentFormat, targetUser.getProperty("keyed_name",""), SourceAssignmentList[i].getProperty("comments",""));
            userCommentList.Add(tmpMailComment);
            
            if(SourceAssignmentList[i].getProperty("path") == "Reject" || SourceAssignmentList[i].getProperty("path") == YryrRejectPathName)
            {
                comment = SourceAssignmentList[i].getProperty("comments");
                break;
            }
        }
        
        //アクティビティをソースとするパスの中からパス名のワークフローパスを取得
        Item tempWorkflowProcessPath = inn.newItem("Workflow Process Path","get");
        tempWorkflowProcessPath.setProperty("source_id",activityId);
        tempWorkflowProcessPath.setProperty("name",pathName);
        tempWorkflowProcessPath.setAttribute("select", "related_id,label");
        tempWorkflowProcessPath = tempWorkflowProcessPath.apply();
        
        if(tempWorkflowProcessPath.isError() && tempWorkflowProcessPath.getItemCount() == -1)
        {
            //エラー
            errorMessage = CCO.ErrorLookup.Lookup("h4_S_E_0002");
            return inn.newError(errorMessage);
        }
        
        DateTime createdOn = DateTime.MinValue;
        Item relatedActivity = null;
        string relatedActivityId = "";
        
        for(int i = 0;i < tempWorkflowProcessPath.getItemCount();i++)
        {
            relatedActivityId = tempWorkflowProcessPath.getItemByIndex(i).getProperty("related_id");
            Item temprelatedActivity = inn.newItem("Activity","get");
            temprelatedActivity.setProperty("id",relatedActivityId);
            temprelatedActivity.setAttribute("select", "created_on,name");
            temprelatedActivity = temprelatedActivity.apply();
            
            if(temprelatedActivity.isError() && temprelatedActivity.getItemCount() == -1)
            {
                //エラー
                errorMessage = CCO.ErrorLookup.Lookup("h4_S_E_0002");
                return inn.newError(errorMessage);
            }
        
            Item workflowProcessPath = null;
            if(!string.IsNullOrEmpty(temprelatedActivity.getProperty("created_on")))
            {
                if(createdOn == DateTime.MinValue)
                {   
                    createdOn = DateTime.Parse(temprelatedActivity.getProperty("created_on"));
                    relatedActivity = temprelatedActivity;
                    workflowProcessPath = tempWorkflowProcessPath.getItemByIndex(i);
                    pathLabel = workflowProcessPath.getProperty("label");
                }
                if(DateTime.Parse(temprelatedActivity.getProperty("created_on")) > createdOn)
                {
                    createdOn = DateTime.Parse(temprelatedActivity.getProperty("created_on"));
                    relatedActivity = temprelatedActivity;
                    workflowProcessPath = tempWorkflowProcessPath.getItemByIndex(i);
                    pathLabel = workflowProcessPath.getProperty("label");
                }
            }
        }
     
        relatedActivityId = relatedActivity.getProperty("id");
        
        //対象アイテムを取得
        Item workflowProcessActivity = inn.newItem("Workflow Process Activity","get");
        workflowProcessActivity.setProperty("related_id",activityId);
        workflowProcessActivity.setAttribute("select", "source_id");
        workflowProcessActivity = workflowProcessActivity.apply();
        
        if(workflowProcessActivity.isError() && workflowProcessActivity.getItemCount() == -1)
        {
            //エラー
            errorMessage = CCO.ErrorLookup.Lookup("h4_S_E_0002");
            return inn.newError(errorMessage);
        }
        
        string workflowProcessActivitySourceId = workflowProcessActivity.getProperty("source_id");
        Item workflowProcess = inn.newItem("Workflow Process","get");
        workflowProcess.setProperty("id",workflowProcessActivitySourceId);
        workflowProcess.setAttribute("select", "id");
        workflowProcess = workflowProcess.apply();
        
        if(workflowProcess.isError() && workflowProcess.getItemCount() == -1)
        {
            //エラー
            errorMessage = CCO.ErrorLookup.Lookup("h4_S_E_0002");
            return inn.newError(errorMessage);
        }
        
        string workflowProcessId = workflowProcess.getProperty("id");
        Item workflow = inn.newItem("Workflow","get");
        workflow.setProperty("related_id",workflowProcessId);
        workflow.setAttribute("select", "behavior,source_id,source_type");
        workflow = workflow.apply();
        
        if(workflow.isError() && workflow.getItemCount() == -1)
        {
            //エラー
            errorMessage = CCO.ErrorLookup.Lookup("h4_S_E_0002");
            return inn.newError(errorMessage);
        }
        
        for(int i = 0; i < workflow.getItemCount(); i++)
        {
            if(workflow.getItemByIndex(i).getProperty("behavior") == "hard_float")//最新のアイテムに対するワークフローを取得
            {
                workflow = workflow.getItemByIndex(i);
            }
        }
        
        //承認対象特定
        string workflowSourceId = workflow.getProperty("source_id");
        var workflowSourceType = workflow.getProperty("source_type");
        string approveItemType = "";
        Item tempApproveItem = null;
        int pointNumber = 0;
        Item approveItem = null;
        List<string> createrList = new List<string>();
        List<string> reviewerList = new List<string>();
        List<string> approverList = new List<string>();
        Item itemType = null;
        string itemTypeLabel = "";
        string keyName= "";

        var noMailUser = new List<string>();//エラー時表示用 メールのないユーザーは、WFの分岐終了後処理
        var noMailUserForYryrReview = new List<string>();

        if(workflowSourceType == "EC17A836496248498BC080344F060619")//h4_MQPage
        {
            approveItemType = "h4_MQPage";
            tempApproveItem = inn.newItem("h4_MQPage","get");
            tempApproveItem.setProperty("id",workflowSourceId);
            tempApproveItem.setAttribute("select", selectProperty);
            approveItem = tempApproveItem.apply();
            keyName = approveItem.getProperty("keyed_name");
            
            if(approveItem.isError() && approveItem.getItemCount() == -1)
            {
                //エラー
                errorMessage = CCO.ErrorLookup.Lookup("h4_S_E_0002");
                return inn.newError(errorMessage);
            }
            
            Item MQPagePointOuts = inn.newItem("h4_MQPage PointOut","get");
            MQPagePointOuts.setProperty("source_id",workflowSourceId);
            MQPagePointOuts.setAttribute("select", "related_id");
            MQPagePointOuts = MQPagePointOuts.apply();
            
            if(MQPagePointOuts.isError() && MQPagePointOuts.getItemCount() == -1)
            {
                //エラー
                errorMessage = CCO.ErrorLookup.Lookup("h4_S_E_0002");
                return inn.newError(errorMessage);
            }
            
            pointNumber = 0;
            Item MQPageCLN = inn.newItem("h4_MQPage CLN","get");//担当者一覧を取得
            MQPageCLN.setProperty("source_id",workflowSourceId);
            MQPageCLN.setAttribute("select", "related_id,h4_workflow_role");
            MQPageCLN = MQPageCLN.apply();
            
            if(MQPageCLN.isError() && MQPageCLN.getItemCount() == -1)
            {
                //エラー
                errorMessage = CCO.ErrorLookup.Lookup("h4_S_E_0002");
                return inn.newError(errorMessage);
            }
            
            for(int i = 0;i < MQPageCLN.getItemCount();i++)
            {
                //related_idが存在しない場合はエラーとする
                var related_id = MQPageCLN.getItemByIndex(i).getProperty("related_id","");
                if(string.IsNullOrEmpty(related_id))
                {
                    if(isRequestReviewPath)//作業中から確認中へのパスの場合無条件でNullリレーションを禁止
                    {
                        return inn.newError(CCO.ErrorLookup.Lookup("h4_S_E_0005"));
                        //（但し、確認者不在の場合、そもそも作業中から確認中へのパスを表示しないので、これは念のためのチェック）
                    }
                    else//作業中から確認中へのパス以外では、確認中のロールのnullリレーションの場合はnullを許可する それ以外はnull禁止
                    {
                        if(MQPageCLN.getItemByIndex(i).getProperty("h4_workflow_role") == "Reviewer")
                        {
                            continue;
                        }
                        else
                        {
                            return inn.newError(CCO.ErrorLookup.Lookup("h4_S_E_0017"));
                        }
                    }
                }

                Item Identity = inn.newItem("Identity","get");
                Identity.setProperty("id",MQPageCLN.getItemByIndex(i).getProperty("related_id"));
                Identity = Identity.apply();
                
                if(Identity.isError() && Identity.getItemCount() == -1)
                {
                    //エラー
                    errorMessage = CCO.ErrorLookup.Lookup("h4_S_E_0002");
                    return inn.newError(errorMessage);
                }
                
                Item idt0 = MQPageCLN.getItemByIndex(i).getRelatedItem();//ユーザー取得
                if (idt0.getProperty("is_alias", "") != "1")
                {
                        //ユーザーではない
                        continue;
                }
                
                //エイリアスアイデンティティだけが担当者に設定される
                Item ccAlias = inn.newItem("Alias","get");
                ccAlias.setProperty("related_id",MQPageCLN.getItemByIndex(i).getProperty("related_id"));
                ccAlias = ccAlias.apply();
                Item ccUser = inn.newItem("User","get");
                ccUser.setAttribute("id",ccAlias.getProperty("source_id"));
                ccUser = ccUser.apply();
                
                if(MQPageCLN.getItemByIndex(i).getProperty("h4_workflow_role") == "Creater")
                {
                    createrList.Add(ccUser.getProperty("email"));
                    isExist_Creater = true;
                    if(ccUser.getProperty("email","") == ""){ noMailUser.Add(ccUser.getProperty("keyed_name",""));}
                }
                else if(MQPageCLN.getItemByIndex(i).getProperty("h4_workflow_role") == "Reviewer")
                {
                    reviewerList.Add(ccUser.getProperty("email"));
                    isExist_Reviewer = true;
                    if(ccUser.getProperty("email","") == ""){ noMailUser.Add(ccUser.getProperty("keyed_name",""));}
                }
                else if(MQPageCLN.getItemByIndex(i).getProperty("h4_workflow_role") == "Approver")
                {
                    approverList.Add(ccUser.getProperty("email"));
                    isExist_Approver = true;
                    if(ccUser.getProperty("email","") == ""){ noMailUser.Add(ccUser.getProperty("keyed_name",""));}
                }
            }

            //担当者の役割が全部そろっているか確認
            if(isRequestReviewPath)
            {
                if(!(isExist_Creater && isExist_Reviewer && isExist_Approver))
                {
                    //担当者不在エラー
                    return inn.newError(CCO.ErrorLookup.Lookup("h4_S_E_0004"));
                }
            }
            else if(!(isExist_Creater && isExist_Approver))
            {
                //担当者不在エラー
                return inn.newError(CCO.ErrorLookup.Lookup("h4_S_E_0014"));
            }

            for(int i = 0; i < MQPagePointOuts.getItemCount(); i++)
            {
                    Item tempPointOut = inn.newItem("h4_PointOut","get");
                    tempPointOut.setProperty("id",MQPagePointOuts.getItemByIndex(i).getProperty("related_id"));
                    tempPointOut.setAttribute("select", "h4_point_number");
                    tempPointOut = tempPointOut.apply();
                    
                    if(tempPointOut.isError() && tempPointOut.getItemCount() == -1)
                    {
                        //エラー
                        errorMessage = CCO.ErrorLookup.Lookup("h4_S_E_0002");
                        return inn.newError(errorMessage);
                    }
                    
                    string temph4PointNumber = tempPointOut.getProperty("h4_point_number");
                    temph4PointNumber = temph4PointNumber.Substring(3);
                    int.TryParse(temph4PointNumber,out int tempPointNumber);
        
                    if(pointNumber == 0)
                    {
                        pointNumber = tempPointNumber;
                    }
                    
                    if(pointNumber < tempPointNumber)
                    {
                        pointNumber = tempPointNumber;
                    }
        
            }
            
            pointNumber += 1;
        
        }
        else if(workflowSourceType == "DD0E19C0D9DE43E986F27A243FBD2298")//h4_ApprovalWFGroup
        {
            approveItemType = "h4_ApprovalWFGroup";
            tempApproveItem = inn.newItem("h4_ApprovalWFGroup","get");
            tempApproveItem.setProperty("id",workflowSourceId);
            tempApproveItem.setAttribute("select", selectProperty);
            approveItem = tempApproveItem.apply();
            keyName = approveItem.getProperty("keyed_name");
            
            if(approveItem.isError() && approveItem.getItemCount() == -1)
            {
                //エラー
                errorMessage = CCO.ErrorLookup.Lookup("h4_S_E_0002");
                return inn.newError(errorMessage);
            }
            
            Item WFGroupCLN = inn.newItem("h4_ApprovalWFGroup CLN","get");//担当者一覧を取得
            WFGroupCLN.setProperty("source_id",workflowSourceId);
            WFGroupCLN.setAttribute("select", "related_id,h4_workflow_role");
            WFGroupCLN = WFGroupCLN.apply();
            
            if(WFGroupCLN.isError() && WFGroupCLN.getItemCount() == -1)
            {
                //エラー
                errorMessage = CCO.ErrorLookup.Lookup("h4_S_E_0002");
                return inn.newError(errorMessage);
            }

            Item WFGroupPointOuts = inn.newItem("h4_ApprovalWFGroup PointOut","get");
            WFGroupPointOuts.setProperty("source_id",workflowSourceId);
            WFGroupPointOuts.setAttribute("select", "related_id");
            WFGroupPointOuts = WFGroupPointOuts.apply();

            if(WFGroupPointOuts.isError() && WFGroupPointOuts.getItemCount() == -1)
            {
                //エラー
                errorMessage = CCO.ErrorLookup.Lookup("h4_S_E_0002");
                return inn.newError(errorMessage);
            }
            
            //役割リストにアイデンティティを追加する
            for(int i = 0;i < WFGroupCLN.getItemCount();i++)
            {
                //related_idが存在しない場合はエラーとする
                var related_id = WFGroupCLN.getItemByIndex(i).getProperty("related_id","");

                if(string.IsNullOrEmpty(related_id))
                {
                    if(isRequestReviewPath)//作業中から確認中へのパスの場合無条件でNullリレーションを禁止
                    {
                        return inn.newError(CCO.ErrorLookup.Lookup("h4_S_E_0005"));
                        //（但し、確認者不在の場合、そもそも作業中から確認中へのパスを表示しないので、これは念のためのチェック）
                    }
                    else//作業中から確認中へのパス以外では、確認中のロールのnullリレーションの場合はnullを許可する それ以外はnull禁止
                    {
                        if(WFGroupCLN.getItemByIndex(i).getProperty("h4_workflow_role") == "Reviewer")
                        {
                            continue;
                        }
                        else
                        {
                            return inn.newError(CCO.ErrorLookup.Lookup("h4_S_E_0017"));
                        }
                    }
                }

                Item Identity = inn.newItem("Identity","get");
                Identity.setProperty("id",WFGroupCLN.getItemByIndex(i).getProperty("related_id"));
                Identity = Identity.apply();
                if(Identity.isError() && Identity.getItemCount() == -1)
                {
                    //エラー
                    errorMessage = CCO.ErrorLookup.Lookup("h4_S_E_0002");
                    return inn.newError(errorMessage);
                }
                
                Item idt0 = WFGroupCLN.getItemByIndex(i).getRelatedItem();//ユーザー取得
                if (idt0.getProperty("is_alias", "") != "1")
                {
                        //ユーザーではない
                        continue;
                }
                
                //エイリアスアイデンティティだけが担当者に設定される
                Item ccAlias = inn.newItem("Alias","get");
                ccAlias.setProperty("related_id",WFGroupCLN.getItemByIndex(i).getProperty("related_id"));
                ccAlias = ccAlias.apply();
                Item ccUser = inn.newItem("User","get");
                ccUser.setAttribute("id",ccAlias.getProperty("source_id"));
                ccUser = ccUser.apply();
                
                if(WFGroupCLN.getItemByIndex(i).getProperty("h4_workflow_role") == "Creater")
                {
                    createrList.Add(ccUser.getProperty("email"));
                    isExist_Creater = true;
                    if(ccUser.getProperty("email","") == ""){ noMailUser.Add(ccUser.getProperty("keyed_name",""));}
                }
                else if(WFGroupCLN.getItemByIndex(i).getProperty("h4_workflow_role") == "Reviewer")
                {
                    reviewerList.Add(ccUser.getProperty("email"));
                    isExist_Reviewer = true;
                    if(ccUser.getProperty("email","") == ""){ noMailUser.Add(ccUser.getProperty("keyed_name",""));}
                }
                else if(WFGroupCLN.getItemByIndex(i).getProperty("h4_workflow_role") == "Approver")
                {
                    approverList.Add(ccUser.getProperty("email"));
                    isExist_Approver = true;
                    if(ccUser.getProperty("email","") == ""){ noMailUser.Add(ccUser.getProperty("keyed_name",""));}
                }
            }

            //担当者の役割が全部そろっているか確認
            if(isRequestReviewPath)
            {
                if(!(isExist_Creater && isExist_Reviewer && isExist_Approver))
                {
                    //担当者不在エラー
                    return inn.newError(CCO.ErrorLookup.Lookup("h4_S_E_0004"));
                }
            }
            else if(!(isExist_Creater && isExist_Approver))
            {
                //担当者不在エラー
                return inn.newError(CCO.ErrorLookup.Lookup("h4_S_E_0014"));
            }

            for(int i = 0; i < WFGroupPointOuts.getItemCount(); i++)
            {
                if(WFGroupPointOuts.getItemByIndex(i).getRelatedItem() != null)
                {
                    Item tempPointOut = inn.newItem("h4_PointOut","get");
                    tempPointOut.setProperty("id",WFGroupPointOuts.getItemByIndex(i).getProperty("related_id"));
                    tempPointOut.setAttribute("select", "h4_point_number");
                    tempPointOut = tempPointOut.apply();

                    if(tempPointOut.isError() && tempPointOut.getItemCount() == -1)
                    {
                        //エラー
                        errorMessage = CCO.ErrorLookup.Lookup("h4_S_E_0002");
                        return inn.newError(errorMessage);
                    }

                    string temph4PointNumber = tempPointOut.getProperty("h4_point_number");
                    temph4PointNumber = temph4PointNumber.Substring(3);
                    int.TryParse(temph4PointNumber,out int tempPointNumber);

                    if(pointNumber == 0)
                    {
                        pointNumber = tempPointNumber;
                    }

                    if(pointNumber < tempPointNumber)
                    {
                        pointNumber = tempPointNumber;
                    }
                }
            }

            pointNumber += 1;

        }
        else if(workflowSourceType == "984B394A7FF14AD8B3E11EE939283344")//h4_Test_Result
        {
