        mailItem.setProperty("body_html",mailBody);
        string subject = mailItem.getProperty("subject");
        subject = subject.Replace("{Path}",pathLabel);
        subject = subject.Replace("{KeyName}",keyName+"【マルQ】");
        mailItem.setProperty("subject",subject);
        
        //送信元アドレスを取得
        string fromUserID = mailItem.getProperty("from_user");
        Item fromUser = inn.newItem("User","get");
        fromUser.setAttribute("id",fromUserID);
        fromUser.setAttribute("select","email");
        fromUser = fromUser.apply();
        string fromAddress = fromUser.getProperty("email");
        
        //メール送信メソッドh4_sendMailへ送信するメールと送信先アイデンティティのリスト、送信先アクティビティを渡す
        RequestState.Add("fromAddress",fromAddress);//from
        RequestState.Add("Subject",mailItem.getProperty("subject"));
        RequestState.Add("Body",mailItem.getProperty("body_html"));
        RequestState.Add("ccList",ccList);
        RequestState.Add("createrList",createrList);
        RequestState.Add("reviewerList",reviewerList);
        RequestState.Add("approverList",approverList);
        RequestState.Add("nextActivity",relatedActivity.getProperty("name"));
        RequestState.Add("targetItemId",workflowSourceId);
        RequestState.Add("h4_isYryrReviewType",isYryrReviewType);
    }
}
return this;
